import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on mean difference and Welch's t-test
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)
            candidates.append((fid, abs(mean_diff), abs(t_stat)))

    # Sort by effect size and t-statistic
    candidates.sort(key=lambda x: (x[1], x[2]), reverse=True)

    # Remove near-duplicates (correlated features)
    keep = []
    correlated_pairs = set()
    for i in range(len(candidates)):
        fid1 = candidates[i][0]
        for j in range(i+1, len(candidates)):
            fid2 = candidates[j][0]
            if (fid1, fid2) in correlated_pairs or (fid2, fid1) in correlated_pairs:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                correlated_pairs.add((fid1, fid2))
                if len(keep) < MAX_DRIVERS:
                    keep.append(fid1)
            elif len(keep) < MAX_DRIVERS:
                keep.append(fid1)
                break

    # Try to find interaction terms among top candidates
    top_features = [f for f in keep[:MAX_DRIVERS]]
    best_product = None
    best_score = -np.inf

    # Check all pairs for significant interaction
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            fid1, fid2 = top_features[i], top_features[j]
            col1, col2 = feats.column(fid1), feats.column(fid2)

            # Create interaction term
            interaction = feats.x[:, col1] * feats.x[:, col2]

            # Fit logistic regression with interaction term
            X = np.column_stack([feats.x[:, col1], feats.x[:, col2], interaction])
            model = LogisticRegression(penalty='l1', solver='liblinear', C=0.1)
            try:
                model.fit(X, feats.y)
                score = model.score(X, feats.y)
                if score > best_score:
                    best_score = score
                    best_product = (fid1, fid2)
            except:
                continue

    # Return design with interaction term if found
    if best_product:
        return Design(
            drivers=(best_product[0],),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={best_product[0]: 1.0}
        )

    # Otherwise, return empty design (no mechanism)
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

